using System;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using Mori;

namespace MoriDesk {
 internal static class CanvasTextLayoutTests {
  const BindingFlags Hidden=BindingFlags.Instance|BindingFlags.NonPublic;
  static double TextHeight(string value,double width,double font){var text=new FormattedText(value,CultureInfo.CurrentCulture,FlowDirection.LeftToRight,new Typeface("Microsoft YaHei UI"),font,Brushes.Black);text.MaxTextWidth=width;return text.Height;}
  static double Height(FreeCanvasItem item){return Math.Max(38,TextHeight(item.Text,item.Width,item.FontSize));}
  static FreeCanvasItem Item(FreeCanvasWindow window,string id){return window.DocumentForTests.Items.Single(i=>i.Id==id);}
  static FreeCanvasViewport View(FreeCanvasWindow window){return (FreeCanvasViewport)typeof(FreeCanvasWindow).GetField("view",Hidden).GetValue(window);}
  static RenderTargetBitmap Render(FreeCanvasWindow window){var content=(FrameworkElement)window.Content;content.Width=1000;content.Height=700;content.Measure(new Size(1000,700));content.Arrange(new Rect(0,0,1000,700));content.UpdateLayout();var image=new RenderTargetBitmap(1000,700,96,96,PixelFormats.Pbgra32);image.Render(content);return image;}
  static int InkPixels(RenderTargetBitmap image,FreeCanvasWindow window,int x,int y,int width,int height){var content=(FrameworkElement)window.Content;Point offset=window.SurfaceForTests.TranslatePoint(new Point(),content);byte[] pixels=new byte[width*height*4];image.CopyPixels(new Int32Rect((int)offset.X+x,(int)offset.Y+y,width,height),pixels,width*4,0);var background=((SolidColorBrush)Theme.Brush("Canvas")).Color;int count=0;for(int i=0;i<pixels.Length;i+=4)if(pixels[i]!=background.B||pixels[i+1]!=background.G||pixels[i+2]!=background.R)count++;return count;}
  internal static void Run(string root,Action<bool,string> check){
   Directory.CreateDirectory(root);var app=Application.Current??new Application();var shutdown=app.ShutdownMode;app.ShutdownMode=ShutdownMode.OnExplicitShutdown;string theme=Theme.Current;FreeCanvasWindow window=null,oldWindow=null,reopened=null;
   try{
    Theme.Set("light");string data=Path.Combine(root,"profile");window=new FreeCanvasWindow(data,new Settings());var store=new FreeCanvasStore(data);
    string paragraph=new string('\u4e2d',150);var item=new FreeCanvasItem{Id=Guid.NewGuid().ToString("N"),Kind="text",Text=paragraph,Color="auto",FontSize=22,X=60,Y=80,Width=320,Height=38};window.DrawItemForTests(item);
    double height=TextHeight(paragraph,item.Width,item.FontSize);check(height>100,"wrapped-text witness extends beyond the former one-line box");
    check(window.HitForTests(new Point(item.X+8,item.Y+height-4))==item,"wrapped canvas text can be selected on its visible final line, not only its first line");
    window.UndoForTests();check(window.ItemCount==0&&window.TextLayoutCountForTests==0,"undoing text insertion also releases its cached layout");
    item=window.AddText(paragraph,new Point(60,80));string id=item.Id;check(item.FontSize==22&&item.Width==320&&Math.Abs(item.Height-Height(item))<.001,"actual add-text action measures automatic wrapping with the existing font and default width");
    check(window.SaveForTests()&&store.Load(window.DocumentForTests.Id).Items.Single().Height==item.Height,"new wrapped text persists its complete measured bounds");
    check(window.EditText(id,"标题")&&Item(window,id).Height==38,"editing a paragraph down to one short line shrinks the writing box");
    string multiline="第一行\n第二行\n第三行\n第四行\n第五行\n第六行";check(window.EditText(id,multiline)&&Item(window,id).Height>100&&Math.Abs(Item(window,id).Height-Height(Item(window,id)))<.001,"double-click edit action grows bounds for additional explicit lines");
    window.UndoForTests();check(Item(window,id).Text=="标题"&&Item(window,id).Height==38,"edit undo restores short text and its geometry together");window.UndoForTests();item=Item(window,id);check(item.Text==paragraph&&Math.Abs(item.Height-height)<.001,"second edit undo restores the complete wrapped paragraph bounds");
    double oldHeight=item.Height;window.ResizeForTests(id,"se",new Point(item.X+160,item.Y+100));item=Item(window,id);check(item.Width==160&&item.FontSize==22&&item.Height>oldHeight&&Math.Abs(item.Height-Height(item))<.001,"narrowing the actual resize route reflows text instead of clipping it to the mouse-drag height");
    check(window.HitForTests(new Point(item.X+8,item.Y+item.Height-4))==item,"resized paragraph remains selectable on its new final line");window.UndoForTests();item=Item(window,id);check(item.Width==320&&Math.Abs(item.Height-oldHeight)<.001,"resize undo restores writing width and full wrapped height");
    double bottom=item.Y+item.Height;window.ResizeForTests(id,"nw",new Point(item.X-160,item.Y-100));item=Item(window,id);check(item.Width==480&&Math.Abs(item.Y+item.Height-bottom)<.001,"north-corner text resize keeps its opposite bottom anchor after reflow");window.UndoForTests();item=Item(window,id);
    Render(window);int builds=window.TextLayoutBuildsForTests;for(int i=0;i<20;i++)window.HitForTests(new Point(item.X+8,item.Y+item.Height-4));Render(window);Render(window);check(window.TextLayoutBuildsForTests==builds,"unchanged text picking and repeated paint reuse one formatted layout");
    var view=View(window);view.Zoom=2;Render(window);view.Zoom=.25;Render(window);view.Zoom=1;Render(window);check(window.TextLayoutBuildsForTests==builds,"viewport zoom scales cached text and its geometry without rebuilding each item");
    item.FontSize=42;window.HitForTests(new Point(item.X+8,item.Y+8));check(item.Height>oldHeight&&Math.Abs(item.Height-Height(item))<.001&&window.TextLayoutBuildsForTests==builds+1,"font-size changes invalidate metrics and wrapping exactly once");item.FontSize=22;window.HitForTests(new Point(item.X+8,item.Y+8));
    var narrow=window.AddText("中",new Point(600,80));string narrowId=narrow.Id;window.ResizeForTests(narrowId,"se",new Point(narrow.X+4,narrow.Y+4));narrow=Item(window,narrowId);check(narrow.Width>=narrow.FontSize&&window.HitForTests(new Point(narrow.X+17,narrow.Y+12))==narrow,"a writing box cannot shrink below one readable character or leave the visible glyph outside its hit area");window.UndoForTests();narrow=Item(window,narrowId);double right=narrow.X+narrow.Width,narrowBottom=narrow.Y+narrow.Height;window.ResizeForTests(narrowId,"nw",new Point(right-4,narrowBottom-4));narrow=Item(window,narrowId);check(narrow.Width>=narrow.FontSize&&Math.Abs(narrow.X+narrow.Width-right)<.001&&Math.Abs(narrow.Y+narrow.Height-narrowBottom)<.001,"clamping a narrow north-west text resize preserves both opposite anchors");window.UndoForTests();window.UndoForTests();check(!window.DocumentForTests.Items.Any(i=>i.Id==narrowId),"temporary narrow-text insertion and both resize gestures remain undoable");
    window.MoveForTests(id,new Vector(0,-160));item=Item(window,id);var image=Render(window);check(item.Y<0&&InkPixels(image,window,64,16,100,60)>15,"text whose first line is offscreen still renders its visible lower lines");window.UndoForTests();item=Item(window,id);
    foreach(string appearance in new[]{"light","dark"}){Theme.Set(appearance);image=Render(window);check(Math.Abs(item.Height-Height(item))<.001&&InkPixels(image,window,64,84,100,40)>15,"cached automatic text remains visible with matching geometry in "+appearance+" theme");}
    window.FitForTests();view=View(window);var topLeft=view.Screen(new Point(item.X,item.Y));var bottomRight=view.Screen(new Point(item.X+item.Width,item.Y+item.Height));check(topLeft.X>=40&&topLeft.Y>=40&&bottomRight.X<=window.SurfaceForTests.ActualWidth-40&&bottomRight.Y<=window.SurfaceForTests.ActualHeight-40,"fit-all includes the measured final line with viewport padding");
    check(window.SaveForTests(),"edited, resized and undo-restored text saves successfully");string project=window.DocumentForTests.Id;double savedHeight=item.Height;window.Close();window=null;reopened=new FreeCanvasWindow(data,new Settings());item=Item(reopened,id);check(reopened.DocumentForTests.Id==project&&item.Text==paragraph&&item.Height==savedHeight&&!reopened.DirtyForTests,"close and reopen retain the paragraph and measured bounds without creating a dirty draft");
    check(reopened.EditText(id,"保存以后仍可撤销")&&reopened.SaveForTests(),"edit can be committed before undo");reopened.UndoForTests();check(reopened.SaveForTests()&&store.Load(project).Items.Single().Text==paragraph&&store.Load(project).Items.Single().Height==savedHeight,"undo after committed edit restores both text and bounds to disk");
    reopened.DeleteForTests(id);check(reopened.TextLayoutCountForTests==0,"deleting text releases cached formatting while keeping undo available");reopened.UndoForTests();check(reopened.HitForTests(new Point(item.X+8,item.Y+savedHeight-4))!=null,"undo deletion rebuilds a usable final-line hit area");
    string legacyData=Path.Combine(root,"legacy");var legacyStore=new FreeCanvasStore(legacyData);var old=legacyStore.Create("旧版单行高度");var oldItem=Item(reopened,id).Copy();oldItem.Id=Guid.NewGuid().ToString("N");oldItem.Height=38;old.Items.Add(oldItem);var oldNarrow=new FreeCanvasItem{Id=Guid.NewGuid().ToString("N"),Kind="text",Text="中",Color="auto",FontSize=22,X=600,Y=80,Width=4,Height=38};old.Items.Add(oldNarrow);legacyStore.Save(old);string manifest=Path.Combine(legacyStore.Root,old.Id,"project.json");byte[] legacyBytes=File.ReadAllBytes(manifest);oldWindow=new FreeCanvasWindow(legacyData,new Settings());var migrated=oldWindow.DocumentForTests.Items.Single(i=>i.Id==oldItem.Id);
    check(migrated.Height>100&&oldWindow.HitForTests(new Point(migrated.X+8,migrated.Y+migrated.Height-4))==migrated,"legacy text uses correct complete bounds immediately upon loading");var migratedNarrow=Item(oldWindow,oldNarrow.Id);check(migratedNarrow.Width>=migratedNarrow.FontSize&&oldWindow.HitForTests(new Point(migratedNarrow.X+17,migratedNarrow.Y+12))==migratedNarrow,"legacy extremely narrow text gains readable width and a complete glyph hit area");check(!oldWindow.DirtyForTests&&File.ReadAllBytes(manifest).SequenceEqual(legacyBytes),"reading legacy text fixes visible geometry without silently rewriting its existing project record");oldWindow.Close();oldWindow=null;check(File.ReadAllBytes(manifest).SequenceEqual(legacyBytes),"closing an unedited legacy canvas keeps the old manifest byte-for-byte unchanged");
    check(!reopened.IsVisible,"all text fixtures remain offscreen and never change a real desktop window");
   }finally{if(window!=null)window.Close();if(oldWindow!=null)oldWindow.Close();if(reopened!=null)reopened.Close();Theme.Set(theme);app.ShutdownMode=shutdown;}
  }
 }
}
